contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address receiver, uint amount) public payable {
        require(caller != address(0) && receiver != address(0));
        // ensure this contract has enough balance to cover transfer when acting as owner
        if (address(this).balance < amount) return; // avoid sending when insufficient funds

        // We must call sendTo as if msg.sender == caller. To simulate different caller,
        // we rely on that the test harness will call run and then perform a low-level
        // call to c from this contract; since we cannot change msg.sender here,
        // we instead reason about the observable behavior: when caller != owner,
        // original contract reverts, so a call from that non-owner would revert.
        // We simulate by calling c.sendTo and observing revert; the property asserts
        // that when caller != owner, the call reverts.

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the initiator is not the owner, sendTo should revert.
        // We cannot read owner, so we express the rule as: when the provided caller
        // is different from this contract (a stand-in for owner), the call must revert.
        // This captures that only owner can succeed. (caller is the hypothetical caller)
        assert(caller == address(this) || reverted);
    }
    receive() external payable {}
}

